import{_ as a,o as i,c as l,ae as r}from"./chunks/framework.RRduUuAx.js";const p=JSON.parse('{"title":"Fork Strategy: co(lab) Week 1","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/20260226-helios-market-research/12_FORK_STRATEGY.md","filePath":"sessions/20260226-helios-market-research/12_FORK_STRATEGY.md"}'),t={name:"sessions/20260226-helios-market-research/12_FORK_STRATEGY.md"};function o(n,e,s,d,c,u){return i(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="fork-strategy-co-lab-week-1" tabindex="-1">Fork Strategy: co(lab) Week 1 <a class="header-anchor" href="#fork-strategy-co-lab-week-1" aria-label="Permalink to &quot;Fork Strategy: co(lab) Week 1&quot;">​</a></h1><p>Date: 2026-02-26 Target Base: <code>blackboardsh/colab</code> Objective: Use co(lab) as acceleration base while stripping non-core surfaces for Helios terminal-first architecture.</p><h2 id="helios-lock-reference" tabindex="-1">Helios Lock (Reference) <a class="header-anchor" href="#helios-lock-reference" aria-label="Permalink to &quot;Helios Lock (Reference)&quot;">​</a></h2><ul><li>Shell: ElectroBun</li><li>Renderers: ghostty + rio (feature-flagged)</li><li>Worktree/lane orchestrator: par</li><li>Mux core: zellij</li><li>Durability/collab: zmx + upterm + tmate</li><li>Protocols: ACP + MCP + A2A + internal local bus</li></ul><h2 id="week-1-goals" tabindex="-1">Week 1 Goals <a class="header-anchor" href="#week-1-goals" aria-label="Permalink to &quot;Week 1 Goals&quot;">​</a></h2><ol><li>Establish fork and compile baseline.</li><li>Remove editor/browser-heavy UX from hot path.</li><li>Install Helios runtime boundary and protocol spine.</li><li>Preserve only reusable shell/workspace/settings primitives.</li></ol><h2 id="keep-rewrite-delete-matrix" tabindex="-1">Keep / Rewrite / Delete Matrix <a class="header-anchor" href="#keep-rewrite-delete-matrix" aria-label="Permalink to &quot;Keep / Rewrite / Delete Matrix&quot;">​</a></h2><h3 id="keep-as-is-or-light-adaptation" tabindex="-1">KEEP (as-is or light adaptation) <a class="header-anchor" href="#keep-as-is-or-light-adaptation" aria-label="Permalink to &quot;KEEP (as-is or light adaptation)&quot;">​</a></h3><ul><li>Desktop shell bootstrap, window lifecycle, app settings persistence.</li><li>Command palette scaffolding and global keyboard routing foundation.</li><li>Workspace/project container and navigation primitives.</li><li>Plugin loading skeleton only if it is decoupled and lazy-loaded.</li><li>Basic telemetry/event dispatch plumbing (if non-blocking).</li></ul><h3 id="rewrite-required-for-helios" tabindex="-1">REWRITE (required for Helios) <a class="header-anchor" href="#rewrite-required-for-helios" aria-label="Permalink to &quot;REWRITE (required for Helios)&quot;">​</a></h3><ul><li>Main-stage layout: <ul><li>rewrite to terminal-first canvas + lanes/panes/tabs model.</li></ul></li><li>Runtime boundary: <ul><li>replace existing runtime coupling with local bus contract (<code>helios.localbus.v1</code>).</li></ul></li><li>Task/workspace orchestration: <ul><li>integrate <code>par</code> lane lifecycle instead of co(lab)-native workflow model.</li></ul></li><li>Session runtime: <ul><li>integrate <code>zellij</code> + <code>zmx</code> lifecycle.</li></ul></li><li>Collaboration flow: <ul><li>add <code>upterm</code>/<code>tmate</code> share controls and policy gates.</li></ul></li><li>AI integration layer: <ul><li>adapt to ACP client boundary + MCP tool bridge + A2A external federation.</li></ul></li><li>Renderer subsystem: <ul><li>implement dual adapter model for <code>ghostty</code> and <code>rio</code> with switch semantics.</li></ul></li></ul><h3 id="delete-week-1-hard-cuts" tabindex="-1">DELETE (week-1 hard cuts) <a class="header-anchor" href="#delete-week-1-hard-cuts" aria-label="Permalink to &quot;DELETE (week-1 hard cuts)&quot;">​</a></h3><ul><li>Browser/editor-first panes in primary workspace.</li><li>Heavy DOM-rich/editor models that are not required for terminal/chat surfaces.</li><li>Any synchronous indexing/render work on UI thread in terminal hot path.</li><li>Non-essential starter/app-builder flows not tied to Helios runtime core.</li><li>Optional novelty modules that increase startup/memory without helping lane/session control.</li></ul><h2 id="week-1-execution-plan" tabindex="-1">Week 1 Execution Plan <a class="header-anchor" href="#week-1-execution-plan" aria-label="Permalink to &quot;Week 1 Execution Plan&quot;">​</a></h2><h3 id="day-1-fork-baseline-and-safety" tabindex="-1">Day 1: Fork Baseline and Safety <a class="header-anchor" href="#day-1-fork-baseline-and-safety" aria-label="Permalink to &quot;Day 1: Fork Baseline and Safety&quot;">​</a></h3><ul><li>Fork/import co(lab) into Helios workspace path.</li><li>Add branch protection and baseline CI smoke checks.</li><li>Capture startup/memory baseline metrics before changes.</li></ul><h3 id="day-2-surface-reduction" tabindex="-1">Day 2: Surface Reduction <a class="header-anchor" href="#day-2-surface-reduction" aria-label="Permalink to &quot;Day 2: Surface Reduction&quot;">​</a></h3><ul><li>Remove editor/browser primary surfaces.</li><li>Stand up terminal-first shell layout placeholders: <ul><li>left rail (workspaces/lanes)</li><li>center terminal canvas</li><li>right rail (approvals/diff/audit)</li></ul></li></ul><h3 id="day-3-protocol-spine" tabindex="-1">Day 3: Protocol Spine <a class="header-anchor" href="#day-3-protocol-spine" aria-label="Permalink to &quot;Day 3: Protocol Spine&quot;">​</a></h3><ul><li>Wire local bus envelope/method/topic definitions.</li><li>Connect UI state transitions to local bus events.</li><li>Stub ACP/MCP/A2A boundaries as adapters.</li></ul><h3 id="day-4-runtime-integrations" tabindex="-1">Day 4: Runtime Integrations <a class="header-anchor" href="#day-4-runtime-integrations" aria-label="Permalink to &quot;Day 4: Runtime Integrations&quot;">​</a></h3><ul><li>Add wrappers and adapter contracts for: <ul><li><code>par</code></li><li><code>zellij</code></li><li><code>zmx</code></li><li><code>upterm</code></li><li><code>tmate</code></li></ul></li><li>Implement lane/session state machine wiring.</li></ul><h3 id="day-5-renderer-split" tabindex="-1">Day 5: Renderer Split <a class="header-anchor" href="#day-5-renderer-split" aria-label="Permalink to &quot;Day 5: Renderer Split&quot;">​</a></h3><ul><li>Implement renderer adapter interface.</li><li>Add <code>renderer_engine</code> setting + switch command path.</li><li>Support hot swap attempt with restart fallback.</li></ul><h3 id="day-6-perf-pass-1" tabindex="-1">Day 6: Perf Pass 1 <a class="header-anchor" href="#day-6-perf-pass-1" aria-label="Permalink to &quot;Day 6: Perf Pass 1&quot;">​</a></h3><ul><li>Add frame-time and input-to-render instrumentation.</li><li>Apply buffer bounds/backpressure and lazy panel mount rules.</li><li>Verify no heavy non-terminal work in hot path.</li></ul><h3 id="day-7-stabilize-and-review" tabindex="-1">Day 7: Stabilize and Review <a class="header-anchor" href="#day-7-stabilize-and-review" aria-label="Permalink to &quot;Day 7: Stabilize and Review&quot;">​</a></h3><ul><li>Produce week-1 report with: <ul><li>diff summary (kept/rewritten/deleted)</li><li>perf deltas</li><li>known blockers</li></ul></li></ul><h2 id="hard-guardrails" tabindex="-1">Hard Guardrails <a class="header-anchor" href="#hard-guardrails" aria-label="Permalink to &quot;Hard Guardrails&quot;">​</a></h2><ul><li>No feature additions outside locked Helios stack during week 1.</li><li>No direct dependency on distributed orchestration in PTY hot path.</li><li>No unbounded terminal or event buffers.</li><li>No share-session defaults without policy gate.</li></ul><h2 id="acceptance-criteria-end-of-week-1" tabindex="-1">Acceptance Criteria (End of Week 1) <a class="header-anchor" href="#acceptance-criteria-end-of-week-1" aria-label="Permalink to &quot;Acceptance Criteria (End of Week 1)&quot;">​</a></h2><ol><li>Fork builds and runs with Helios terminal-first shell.</li><li>Local bus events drive core UI state.</li><li>Adapter stubs for par/zellij/zmx/upterm/tmate in place and callable.</li><li>Renderer feature flag available and wired to switch path.</li><li>Editor/browser-heavy modules removed from primary interaction path.</li><li>Baseline performance report produced for next optimization wave.</li></ol>',32)])])}const m=a(t,[["render",o]]);export{p as __pageData,m as default};
